target.css:
:root {
  --ink: #24333b;
  --muted: #68777c;
  --paper: #fffdf7;
  --line: #d8dfd8;
  --teal: #167b78;
  --teal-soft: #dcefed;
  --coral: #dc725d;
  --coral-soft: #fae4de;
}

.language-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-top: 5px solid var(--teal);
  border-radius: 14px;
  color: var(--ink);
}

.card-header,
.card-footer,
.progress-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-header {
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--teal);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 22px;
  line-height: 1.1;
}

.session-code {
  padding: 6px 9px;
  border-radius: 7px;
  background: var(--coral-soft);
  color: var(--coral);
  font-size: 12px;
  font-weight: 800;
}

.lesson-grid {
  display: grid;
  grid-template-columns: 1.35fr 0.9fr;
  gap: 18px;
  padding: 15px 0;
}

.lesson-main h2 {
  font-size: 16px;
  line-height: 1.25;
}

.lesson-main p {
  margin-top: 5px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.4;
}

.progress-block {
  margin-top: 15px;
}

.progress-label {
  margin-bottom: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.progress-label strong {
  color: var(--teal);
}

.progress-track {
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--teal-soft);
}

.progress-fill {
  display: block;
  width: 60%;
  height: 100%;
  border-radius: inherit;
  background: var(--teal);
}

.meta-list {
  display: grid;
  gap: 7px;
}

.meta-list div {
  padding: 7px 9px;
  border-left: 3px solid var(--coral);
  background: var(--coral-soft);
}

.meta-list span,
.meta-list strong {
  display: block;
}

.meta-list span {
  color: var(--coral);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.meta-list strong {
  margin-top: 2px;
  font-size: 12px;
}

.card-footer {
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.status {
  color: var(--teal);
  font-size: 12px;
  font-weight: 700;
}

button {
  padding: 8px 12px;
  border: 0;
  border-radius: 7px;
  background: var(--ink);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

